{"sql": "WITH race_laps AS (
    SELECT DISTINCT race_id, driver_id, lap, position
    FROM lap_positions 
    WHERE race_id = 841 AND lap_type = 'Race' AND lap > 0
)
SELECT driver_id, position FROM race_laps WHERE lap = 1 ORDER BY position"}

